          "code": "import numpy as np\nfrom sklearn.linear_model import LinearRegression, LogisticRegression\nfrom sklearn.metrics import log_loss, mean_squared_error\n\nrng = np.random.default_rng(42)\n\n# Bagian A: Ekuivalensi MLE Gaussian == Minimisasi MSE (OLS)\nn = 500\nX_reg = rng.normal(0.0, 1.0, size=(n, 3))\nw_reg_true = np.array([2.5, -1.3, 0.7])\nsigma_true = 1.5\ny_reg = 0.8 + X_reg @ w_reg_true + rng.normal(0.0, sigma_true, size=n)\n\nols = LinearRegression().fit(X_reg, y_reg)\ny_pred = ols.predict(X_reg)\nmse_val = mean_squared_error(y_reg, y_pred)\nsigma_mle = np.sqrt(mse_val)\nnll_gaussian = 0.5 * n * (np.log(2.0 * np.pi * mse_val) + 1.0)\n\nprint(f\"Gaussian MLE == OLS | MSE={mse_val:.4f} | sigma_MLE={sigma_mle:.4f} | NLL={nll_gaussian:.2f}\")\n\n# Bagian B: Bahaya Complete Separation pada MLE Bernoulli (C sangat besar vs L2)\nX_sep = np.vstack([\n    rng.normal(loc=[-2.0, 0.0], scale=0.6, size=(80, 2)),\n    rng.normal(loc=[2.0, 0.0], scale=0.6, size=(80, 2)),\n])\ny_sep = np.array([0] * 80 + [1] * 80)\n\n# Hampir tanpa regularisasi (C=1e9) vs L2 moderat (C=1.0)\nmle_unreg = LogisticRegression(C=1e9, solver=\"lbfgs\", max_iter=1000).fit(X_sep, y_sep)\nmap_l2 = LogisticRegression(C=1.0, solver=\"lbfgs\", max_iter=1000).fit(X_sep, y_sep)\n\nll_unreg = log_loss(y_sep, mle_unreg.predict_proba(X_sep)[:, 1])\nll_l2 = log_loss(y_sep, map_l2.predict_proba(X_sep)[:, 1])\n\nprint(\"--- Audit Complete Separation pada Klasifikasi Biner ---\")\nprint(f\"  MLE (C=1e9) | ||w||_2={np.linalg.norm(mle_unreg.coef_):7.3f} | LogLoss={ll_unreg:.6f} | w={np.round(mle_unreg.coef_[0], 3)}\")\nprint(f\"  L2  (C=1.0) | ||w||_2={np.linalg.norm(map_l2.coef_):7.3f} | LogLoss={ll_l2:.6f} | w={np.round(map_l2.coef_[0], 3)}\")",
