          "id": "code-ml-03-1-ch03_1_diag",
          "title": "Diagnostik Produksi: Audit Condition Number Fisher & Risiko Sign-Flip",
          "language": "python",
          "filename": "03_1_fisher_collinearity_audit.py",
          "code": "import numpy as np\n\n# Audit Fisher Information Matrix: Dampak Kolinearitas pada Batas Cramer-Rao & Sign-Flip\nrng = np.random.default_rng(42)\nn = 800\ntrue_w = np.array([0.0, 0.8, 0.4])  # Kedua fitur sejatinya bernilai POSITIF\n\ndef audit_fisher_collinearity(rho: float):\n    z1 = rng.normal(0.0, 1.0, size=n)\n    z2 = rng.normal(0.0, 1.0, size=n)\n    x1 = z1\n    x2 = rho * z1 + np.sqrt(max(1.0 - rho**2, 1e-12)) * z2\n    X = np.column_stack([np.ones(n), x1, x2])\n    p = 1.0 / (1.0 + np.exp(-(X @ true_w)))\n    fisher = (X.T * (p * (1.0 - p))) @ X\n\n    eigvals = np.linalg.eigvalsh(fisher)\n    cond_num = eigvals[-1] / eigvals[0]\n    crlb_se = np.sqrt(np.diag(np.linalg.inv(fisher)))\n\n    # Estimasi probabilitas sign-flip untuk w2 (sejati = +0.4)\n    sign_flips = 0\n    n_runs = 200\n    for _ in range(n_runs):\n        y = rng.binomial(1, p)\n        w = np.zeros(3)\n        for _ in range(15):\n            pr = 1.0 / (1.0 + np.exp(-np.clip(X @ w, -30, 30)))\n            I_cur = (X.T * (pr * (1.0 - pr))) @ X + 1e-9 * np.eye(3)\n            w += np.linalg.solve(I_cur, X.T @ (y - pr))\n        if w[2] < 0:\n            sign_flips += 1\n    return cond_num, crlb_se[2], sign_flips / n_runs * 100.0\n\nprint(\"Audit Fisher Information & Risiko Sign-Flip Koefisien (w2_true = +0.40):\")\nprint(f\"{'rho':>6s} | {'Cond(I)':>10s} | {'CRLB SE(w2)':>12s} | {'Sign-Flip Rate':>14s}\")\nprint(\"-\" * 52)\nfor rho in [0.0, 0.70, 0.95, 0.99]:\n    cond_num, se_w2, flip_pct = audit_fisher_collinearity(rho)\n    print(f\"{rho:6.2f} | {cond_num:10.1f} | {se_w2:12.4f} | {flip_pct:13.1f}%\")",
          "expectedOutput": "Audit Fisher Information & Risiko Sign-Flip Koefisien (w2_true = +0.40):\n   rho |    Cond(I) |  CRLB SE(w2) | Sign-Flip Rate\n----------------------------------------------------\n  0.00 |        1.4 |       0.0779 |           0.0%\n  0.70 |        3.8 |       0.1106 |           0.0%\n  0.95 |       22.9 |       0.2565 |           5.5%\n  0.99 |      129.1 |       0.5676 |          21.0%",
