          "code": "import numpy as np\n\n# 1) Empirical Bayes Beta-Binomial untuk Estimasi CTR Cold-Start\nrng = np.random.default_rng(42)\nalpha_true, beta_true = 4.0, 96.0  # Populasi rata-rata CTR = 4.0%\nn_ads = 300\ntrue_ctrs = rng.beta(alpha_true, beta_true, size=n_ads)\n# Impresi historis cukup besar untuk mengestimasi prior populasi via Method of Moments\nhist_impr = rng.integers(500, 3000, size=n_ads)\nhist_clicks = rng.binomial(hist_impr, true_ctrs)\nobs_rates = hist_clicks / hist_impr\n\nmu_hat = obs_rates.mean()\nvar_hat = obs_rates.var(ddof=1)\n# Method of Moments Beta: alpha0 + beta0 = mu*(1-mu)/var - 1\nstrength_eb = max((mu_hat * (1.0 - mu_hat) / var_hat) - 1.0, 2.0)\nalpha_eb = mu_hat * strength_eb\nbeta_eb = (1.0 - mu_hat) * strength_eb\n\nprint(f\"Empirical Bayes Prior Terestimasi: Beta(alpha0={alpha_eb:.2f}, beta0={beta_eb:.2f}), mean={alpha_eb/(alpha_eb+beta_eb):.4f}\")\n\n# Bandingkan ranking kandidat iklan baru (cold-start) vs iklan mapan\ncandidates = [\n    (\"Spam_Baru_1klik\", 1, 1),\n    (\"Produk_Baru_2klik\", 2, 3),\n    (\"Promo_Menengah\", 18, 300),\n    (\"Merchant_Top_Mapan\", 420, 10000),\n    (\"Iklan_Nol_Klik_Baru\", 0, 5),\n]\nprint(\"--- Perbandingan MLE vs Empirical Bayes Beta-Binomial ---\")\nprint(f\"{'Kandidat':20s} | {'k/n':>10s} | {'MLE CTR':>8s} | {'EB Mean':>8s} | {'EB MAP':>8s}\")\nprint(\"-\" * 66)\nfor name, k, n_imp in candidates:\n    mle = k / n_imp\n    post_mean = (alpha_eb + k) / (alpha_eb + beta_eb + n_imp)\n    post_map = (alpha_eb + k - 1.0) / (alpha_eb + beta_eb + n_imp - 2.0)\n    print(f\"{name:20s} | {f'{k}/{n_imp}':>10s} | {mle:8.4f} | {post_mean:8.4f} | {post_map:8.4f}\")\n\n# 2) Pembaruan Konjugat Normal-Normal (Precision-Weighted Shrinkage)\nmu0, tau0 = 100.0, 10.0   # Prior rata-rata biaya klaim = 100, std prior = 10\nsigma_obs = 25.0          # Noise observasi diketahui\nx_bar_obs = 140.0\nprint(\"--- Normal-Normal Conjugate Update (mu0=100, tau0=10, sigma=25, x_bar=140) ---\")\nfor n_obs in [1, 5, 25, 200]:\n    prec_prior = 1.0 / (tau0 ** 2)\n    prec_data = n_obs / (sigma_obs ** 2)\n    mu_post = (prec_prior * mu0 + prec_data * x_bar_obs) / (prec_prior + prec_data)\n    sd_post = np.sqrt(1.0 / (prec_prior + prec_data))\n    print(f\"  n={n_obs:3d} -> posterior mean={mu_post:6.2f}, posterior std={sd_post:5.2f}\")",
