          "code": "import numpy as np\nfrom sklearn.linear_model import Lasso, Ridge\n\n# Verifikasi Eksak Dualitas Prior-Regularisasi:\n# 1) MAP Gaussian Prior w ~ N(0, tau^2 I) == Ridge(alpha = sigma^2 / tau^2)\n# 2) MAP Laplace  Prior w_j ~ Laplace(0, b) == Lasso(alpha = sigma^2 / (n * b))\nrng = np.random.default_rng(42)\nn, d = 300, 8\nX = rng.normal(0.0, 1.0, size=(n, d))\nw_true = np.array([2.0, -1.5, 0.0, 0.0, 0.8, 0.0, -0.4, 0.0])\nsigma = 1.2\ny = X @ w_true + rng.normal(0.0, sigma, size=n)\n\n# --- A. Gaussian MAP vs Ridge ---\ntau = 0.6\nlambda_ridge = (sigma ** 2) / (tau ** 2)\nw_map_gauss = np.linalg.solve(X.T @ X + lambda_ridge * np.eye(d), X.T @ y)\nridge = Ridge(alpha=lambda_ridge, fit_intercept=False).fit(X, y)\ndiff_ridge = np.max(np.abs(w_map_gauss - ridge.coef_))\nprint(f\"Gaussian MAP vs Ridge(alpha={lambda_ridge:.2f}): max|diff| = {diff_ridge:.2e}\")\n\n# --- B. Laplace MAP (Coordinate Descent Proximal) vs Scikit-Learn Lasso ---\nb_laplace = 0.15\n# Objektif MAP Laplace: 1/(2*sigma^2) ||y - Xw||_2^2 + (1/b) ||w||_1\n# Setara dengan objektif sklearn Lasso: 1/(2n) ||y - Xw||_2^2 + alpha ||w||_1\n# sehingga alpha_sklearn = sigma^2 / (n * b)\nalpha_lasso = (sigma ** 2) / (n * b_laplace)\n\ndef map_laplace_cd(X_mat, y_vec, lam_eff, n_iter=400):\n    w = np.zeros(X_mat.shape[1])\n    col_sq = np.sum(X_mat ** 2, axis=0)\n    for _ in range(n_iter):\n        for j in range(X_mat.shape[1]):\n            r_j = y_vec - (X_mat @ w - X_mat[:, j] * w[j])\n            rho_j = float(X_mat[:, j] @ r_j)\n            w[j] = np.sign(rho_j) * max(abs(rho_j) - lam_eff, 0.0) / col_sq[j]\n    return w\n\nw_map_laplace = map_laplace_cd(X, y, lam_eff=(sigma ** 2) / b_laplace)\nlasso = Lasso(alpha=alpha_lasso, fit_intercept=False, tol=1e-10, max_iter=5000).fit(X, y)\ndiff_lasso = np.max(np.abs(w_map_laplace - lasso.coef_))\nn_zero = int(np.sum(np.abs(lasso.coef_) < 1e-6))\n\nprint(f\"Laplace MAP  vs Lasso(alpha={alpha_lasso:.4f}): max|diff| = {diff_lasso:.2e} | Zero weights={n_zero}/{d}\")\nprint(f\"  Ridge coefs (padat) : {np.round(ridge.coef_, 3)}\")\nprint(f\"  Lasso coefs (sparse): {np.round(lasso.coef_, 3)}\")",
