          "code": "import numpy as np\nfrom scipy.spatial.distance import jensenshannon\nfrom scipy.stats import pearsonr, wasserstein_distance\nfrom sklearn.feature_selection import mutual_info_regression\n\n# Bagian A: Perbandingan KL, JS, dan Wasserstein-1 saat Support Bergeser Menjauh\nx_grid = np.linspace(-4.0, 16.0, 2001)\ndx = x_grid[1] - x_grid[0]\nsig = 0.5\np_pdf = np.exp(-0.5 * (x_grid / sig) ** 2)\np_pmf = p_pdf / p_pdf.sum()\n\nprint(\"Pergeseran Support P=N(0, 0.5^2) vs Q=N(delta, 0.5^2):\")\nprint(f\"{'delta':>6s} | {'KL(P||Q)':>11s} | {'JS Div (nats)':>13s} | {'Wasserstein-1':>13s}\")\nprint(\"-\" * 52)\nfor delta in [0.0, 0.5, 2.0, 5.0, 10.0]:\n    q_pdf = np.exp(-0.5 * ((x_grid - delta) / sig) ** 2)\n    q_pmf = q_pdf / q_pdf.sum()\n    # KL analitik untuk dua Gaussian bervarians sama: delta^2 / (2*sig^2)\n    kl_val = (delta ** 2) / (2.0 * sig ** 2)\n    # jensenshannon SciPy mengembalikan akar kuadrat sqrt(JS), jadi dikuadratkan!\n    js_div = float(jensenshannon(p_pmf, q_pmf, base=np.e) ** 2)\n    w1_val = float(wasserstein_distance(x_grid, x_grid, u_weights=p_pmf, v_weights=q_pmf))\n    print(f\"{delta:6.1f} | {kl_val:11.3f} | {js_div:13.4f} | {w1_val:13.4f}\")\n\n# Bagian B: Mutual Information vs Korelasi Pearson pada Relasi Non-Linier Y = X^2 + noise\nrng = np.random.default_rng(42)\nX_nl = rng.uniform(-3.0, 3.0, size=(1200, 2))\ny_nl = X_nl[:, 0] ** 2 + rng.normal(0.0, 0.25, size=1200)\n\nr_f0, _ = pearsonr(X_nl[:, 0], y_nl)\nr_f1, _ = pearsonr(X_nl[:, 1], y_nl)\nmi_scores = mutual_info_regression(X_nl, y_nl, random_state=42)\n\nprint(\"--- Deteksi Dependensi Non-Linier Y = X0^2 + noise (X1 noise murni) ---\")\nprint(f\"  Fitur X0 (kuadratik): Pearson r = {r_f0:+.4f} | Mutual Info = {mi_scores[0]:.4f} nats\")\nprint(f\"  Fitur X1 (indep.)   : Pearson r = {r_f1:+.4f} | Mutual Info = {mi_scores[1]:.4f} nats\")",
