          "language": "python",
          "filename": "03_3_drift_monitor_binning_audit.py",
          "code": "import numpy as np\nfrom scipy.spatial.distance import jensenshannon\nfrom scipy.stats import wasserstein_distance\n\n# Audit Drift Monitoring Produksi: Sensitivitas Jumlah Bin pada KL/PSI vs Wasserstein-1\nrng = np.random.default_rng(42)\nref_income = rng.lognormal(mean=2.3, sigma=0.45, size=1500)      # Referensi (juta IDR)\nprod_mild = rng.lognormal(mean=2.42, sigma=0.45, size=1500)      # Drift ringan +12.7%\nprod_outlier = np.concatenate([ref_income[:1495], np.full(5, 85.0)])  # 5 outlier baru di luar rentang\n\ndef hist_divergences(u, v, n_bins, eps=1e-12):\n    lo = min(u.min(), v.min())\n    hi = max(u.max(), v.max())\n    edges = np.linspace(lo, hi, n_bins + 1)\n    hu, _ = np.histogram(u, bins=edges)\n    hv, _ = np.histogram(v, bins=edges)\n    pu = (hu + eps) / (hu.sum() + eps * n_bins)\n    pv = (hv + eps) / (hv.sum() + eps * n_bins)\n    kl_prod_ref = float(np.sum(pv * np.log(pv / pu)))\n    psi = float(np.sum((pv - pu) * np.log(pv / pu)))\n    js = float(jensenshannon(pu, pv, base=np.e) ** 2)\n    w1_std = float(wasserstein_distance(u, v) / np.std(u))\n    return kl_prod_ref, psi, js, w1_std\n\nprint(\"Audit Drift Monitor — Skenario 1: Drift Populasi Ringan (+12.7% median)\")\nfor b in [5, 15, 60]:\n    kl, psi, js, w1s = hist_divergences(ref_income, prod_mild, n_bins=b)\n    print(f\"  bins={b:2d} | KL(prod||ref)={kl:.4f} | PSI={psi:.4f} | JS={js:.4f} | Std-W1={w1s:.4f}\")\nprint(\"--- Skenario 2: Hanya 5 Outlier Ekstrem (0.33% populasi) di Bin Kosong ---\")\nfor b in [5, 15, 60]:\n    kl, psi, js, w1s = hist_divergences(ref_income, prod_outlier, n_bins=b)\n    print(f\"  bins={b:2d} | KL(prod||ref)={kl:.4f} | PSI={psi:.4f} | JS={js:.4f} | Std-W1={w1s:.4f}\")",
          "expectedOutput": "Audit Drift Monitor — Skenario 1: Drift Populasi Ringan (+12.7% median)\n  bins= 5 | KL(prod||ref)=0.0257 | PSI=0.0500 | JS=0.0062 | Std-W1=0.2709\n  bins=15 | KL(prod||ref)=0.0766 | PSI=0.1136 | JS=0.0097 | Std-W1=0.2709\n  bins=60 | KL(prod||ref)=0.3258 | PSI=0.5079 | JS=0.0165 | Std-W1=0.2709\n--- Skenario 2: Hanya 5 Outlier Ekstrem (0.33% populasi) di Bin Kosong ---\n  bins= 5 | KL(prod||ref)=0.0941 | PSI=0.0975 | JS=0.0012 | Std-W1=0.0498\n  bins=15 | KL(prod||ref)=0.0941 | PSI=0.0975 | JS=0.0012 | Std-W1=0.0498\n  bins=60 | KL(prod||ref)=0.0942 | PSI=0.0975 | JS=0.0012 | Std-W1=0.0498",
