          "code": "import numpy as np\n\n# Bagian A: Pembuktian Bayes-Optimal Point Estimators (L2=Mean, L1=Median, Pinball=Quantile)\nrng = np.random.default_rng(42)\n# Distribusi posterior miring kanan (Log-Normal: durasi pengiriman / ukuran klaim)\ny_post = rng.lognormal(mean=3.0, sigma=0.75, size=20000)\n\npred_mean = float(np.mean(y_post))\npred_median = float(np.median(y_post))\ntau_q = 0.85\npred_q85 = float(np.quantile(y_post, tau_q))\n\ndef eval_losses(a_hat):\n    l2 = float(np.mean((y_post - a_hat) ** 2))\n    l1 = float(np.mean(np.abs(y_post - a_hat)))\n    diff = y_post - a_hat\n    pinball = float(np.mean(np.where(diff >= 0, tau_q * diff, (tau_q - 1.0) * diff)))\n    return l2, l1, pinball\n\nprint(\"Optimal Point Estimators pada Distribusi Log-Normal (Miring Kanan):\")\nprint(f\"{'Kandidat Aksi':18s} | {'Nilai':>7s} | {'E[L2]':>9s} | {'E[L1]':>7s} | {'E[Pinball 0.85]':>15s}\")\nprint(\"-\" * 68)\nfor name, a_val in [(\"Mean (L2*)\", pred_mean), (\"Median (L1*)\", pred_median), (\"Quantile P85*\", pred_q85)]:\n    l2, l1, pb = eval_losses(a_val)\n    print(f\"{name:18s} | {a_val:7.2f} | {l2:9.2f} | {l1:7.2f} | {pb:15.3f}\")\n\n# Bagian B: Kebijakan 3-Aksi (Approve / Reject-Review / Block) di Bawah Biaya Asimetris\ncost_fp, cost_fn, cost_rej = 40.0, 500.0, 20.0\ntau_elkan = cost_fp / (cost_fp + cost_fn)\ntau_low = cost_rej / cost_fn\ntau_high = 1.0 - (cost_rej / cost_fp)\n\n# Simulasi 4000 transaksi dengan probabilitas posterior terkalibrasi\nprobs = rng.beta(0.6, 5.4, size=4000)\ny_true = rng.binomial(1, probs)\n\ndef cost_2action(p_arr, y_arr, tau):\n    act = (p_arr >= tau).astype(int)\n    fp = np.sum((act == 1) & (y_arr == 0))\n    fn = np.sum((act == 0) & (y_arr == 1))\n    return float(fp * cost_fp + fn * cost_fn)\n\ndef cost_3action_reject(p_arr, y_arr, t_lo, t_hi):\n    act_block = p_arr > t_hi\n    act_rev = (p_arr >= t_lo) & (p_arr <= t_hi)\n    act_app = p_arr < t_lo\n    fp = np.sum(act_block & (y_arr == 0))\n    fn = np.sum(act_app & (y_arr == 1))\n    n_rev = int(np.sum(act_rev))\n    total = float(fp * cost_fp + fn * cost_fn + n_rev * cost_rej)\n    return total, n_rev\n\nc_half = cost_2action(probs, y_true, 0.50)\nc_elkan = cost_2action(probs, y_true, tau_elkan)\nc_rej, n_rev = cost_3action_reject(probs, y_true, tau_low, tau_high)\n\nprint(f\"--- Asymmetric Reject Band (C_FP={cost_fp:.0f}, C_FN={cost_fn:.0f}, c_r={cost_rej:.0f}) ---\")\nprint(f\"  Ambang Elkan 2-Aksi : tau* = {tau_elkan:.4f}\")\nprint(f\"  Pita Reject 3-Aksi  : [tau_low={tau_low:.4f}, tau_high={tau_high:.4f}]\")\nprint(f\"  Total Biaya tau=0.50: {c_half:10.1f}\")\nprint(f\"  Total Biaya Elkan   : {c_elkan:10.1f}\")\nprint(f\"  Total Biaya 3-Aksi  : {c_rej:10.1f} (eskalasi manual = {n_rev}/4000 = {n_rev/40:.1f}%)\")",
