          "code": "import numpy as np\nfrom sklearn.calibration import CalibratedClassifierCV\nfrom sklearn.datasets import make_classification\nfrom sklearn.metrics import brier_score_loss, log_loss\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.naive_bayes import GaussianNB\n\n# Mengukur Dampak Kalibrasi Probabilitas terhadap Proper Scoring Rules & Biaya Keputusan\nX, y = make_classification(\n    n_samples=3000, n_features=20, n_informative=4, n_redundant=14,\n    class_sep=1.5, weights=[0.85, 0.15], flip_y=0.03, random_state=42\n)\nX_train, X_test, y_train, y_test = train_test_split(\n    X, y, test_size=0.35, stratify=y, random_state=42\n)\n\n# GaussianNB terkenal overconfident saat 14 fitur redundant saling berkorelasi kuat\nraw_nb = GaussianNB().fit(X_train, y_train)\ncal_sig = CalibratedClassifierCV(GaussianNB(), method=\"sigmoid\", cv=5).fit(X_train, y_train)\ncal_iso = CalibratedClassifierCV(GaussianNB(), method=\"isotonic\", cv=5).fit(X_train, y_train)\n\ndef compute_ece(y_true, y_prob, n_bins=10):\n    edges = np.linspace(0.0, 1.0, n_bins + 1)\n    ece = 0.0\n    for i in range(n_bins):\n        mask = (y_prob >= edges[i]) & (y_prob < edges[i + 1] if i < n_bins - 1 else y_prob <= edges[i + 1])\n        if np.any(mask):\n            ece += (np.sum(mask) / len(y_true)) * abs(y_true[mask].mean() - y_prob[mask].mean())\n    return float(ece)\n\ncost_fp, cost_fn, cost_rej = 40.0, 400.0, 22.0\nt_lo, t_hi = cost_rej / cost_fn, 1.0 - cost_rej / cost_fp\n\nprint(f\"Evaluasi Proper Scoring Rules & Biaya Reject Band [{t_lo:.3f}, {t_hi:.3f}]:\")\nprint(f\"{'Model':22s} | {'LogLoss':>7s} | {'Brier':>7s} | {'ECE':>6s} | {'Total Cost':>10s} | {'Review%':>7s}\")\nprint(\"-\" * 74)\nfor name, clf in [(\"Raw GaussianNB\", raw_nb), (\"Platt Sigmoid Calib.\", cal_sig), (\"Isotonic Calib.\", cal_iso)]:\n    p = clf.predict_proba(X_test)[:, 1]\n    ll = log_loss(y_test, p)\n    bs = brier_score_loss(y_test, p)\n    ece = compute_ece(y_test, p)\n    blk = p > t_hi\n    rev = (p >= t_lo) & (p <= t_hi)\n    app = p < t_lo\n    cost = np.sum(blk & (y_test == 0)) * cost_fp + np.sum(app & (y_test == 1)) * cost_fn + np.sum(rev) * cost_rej\n    print(f\"{name:22s} | {ll:7.4f} | {bs:7.4f} | {ece:6.4f} | {cost:10.1f} | {100.0*rev.mean():6.1f}%\")",
