          "code": "import numpy as np\nfrom sklearn.metrics import accuracy_score, brier_score_loss, log_loss\n\n# Audit Strictly Proper Scoring Rules & Dekomposisi Brier Score Murphy (1973):\n# Brier = Reliability (Calibration Error) - Resolution (Sharpness) + Uncertainty\nrng = np.random.default_rng(42)\nn = 5000\np_true = rng.beta(1.5, 4.5, size=n)\ny = rng.binomial(1, p_true)\n\n# Tiga strategi pelaporan probabilitas:\n# 1) Honest Bayes (q = p_true)\n# 2) Overconfident Sharpening (mempertajam skor menjauh dari 0.5 — sering terjadi di NN!)\n# 3) Underconfident Hedging (menarik semua skor ke 0.5)\nlogits = np.log(p_true / (1.0 - p_true))\nq_honest = p_true\nq_overconf = 1.0 / (1.0 + np.exp(-2.2 * logits))\nq_underconf = 1.0 / (1.0 + np.exp(-0.45 * logits))\n\ndef murphy_brier_decomp(y_true, y_prob, n_bins=10):\n    edges = np.linspace(0.0, 1.0, n_bins + 1)\n    y_bar = float(y_true.mean())\n    rel, res = 0.0, 0.0\n    for i in range(n_bins):\n        mask = (y_prob >= edges[i]) & (y_prob < edges[i + 1] if i < n_bins - 1 else y_prob <= edges[i + 1])\n        if np.any(mask):\n            w = np.sum(mask) / len(y_true)\n            o_k = float(y_true[mask].mean())\n            f_k = float(y_prob[mask].mean())\n            rel += w * ((f_k - o_k) ** 2)\n            res += w * ((o_k - y_bar) ** 2)\n    unc = y_bar * (1.0 - y_bar)\n    return rel, res, unc\n\nprint(\"Audit Strict Propriety: Mengapa Manipulasi Skor Gagal Mengalahkan Probabilitas Sejati:\")\nprint(f\"{'Strategi Skor':22s} | {'Acc@0.5':>7s} | {'LogLoss':>7s} | {'Brier':>7s} | {'Rel(Cal)':>8s} | {'Res':>7s} | {'Unc':>7s}\")\nprint(\"-\" * 82)\nfor name, q in [(\"Honest (q = p_true)\", q_honest), (\"Overconfident (2.2x)\", q_overconf), (\"Underconfident (0.45x)\", q_underconf)]:\n    acc = accuracy_score(y, (q >= 0.5).astype(int))\n    ll = log_loss(y, q)\n    bs = brier_score_loss(y, q)\n    rel, res, unc = murphy_brier_decomp(y, q)\n    print(f\"{name:22s} | {acc:7.4f} | {ll:7.4f} | {bs:7.4f} | {rel:8.5f} | {res:7.5f} | {unc:7.5f}\")",
